import fs from 'node:fs'; import assert from 'node:assert/strict'; import {keccak256,getContractAddress} from 'viem';
const dir='evidence/HO-hsk-mainnet-1/'; const data=fs.readFileSync(dir+'initcode.hex','utf8').trim(); const from='0x04b0A7AFD4Ab71C5d49c4bd578C2D9B8eA7DF36E'; const fixed='0x'+BigInt(29372120).toString(16);
const artifact=JSON.parse(fs.readFileSync('contracts/out/TradingSessionGuard.sol/TradingSessionGuard.json'));
const report={schemaVersion:'hsk-creation-readonly/1',startedAt:new Date().toISOString(),dataMode:'MAINNET_READONLY',sourceSha:'1f1a48d56df96fc6f838d0696f1b5e3500bcf004',chainId:177,from,to:null,value:'0',initcodeKeccak256:keccak256(data),balance:{raw:'0',provenance:'User-reviewed zero-balance observation and reused deploy-preview-unsigned-20261027.json; not re-read to confirm',observedAt:null,endpointScope:['https://mainnet.hsk.xyz','https://hashkey.drpc.org']},providers:[],errors:[],liveFundsEnabled:false,broadcastStatus:'NOT_BROADCAST',wp4Status:'WAITING_GAS',feeCompleteness:'UNKNOWN_CHAIN_SPECIFIC_EXTRA_COMPONENTS',proxyImplementationAdmin:'UNKNOWN_NOT_VERIFIED'};
for(const url of ['https://mainnet.hsk.xyz','https://hashkey.drpc.org']) {
 const record={endpoint:url,observedAt:new Date().toISOString(),rpcMethods:[],reads:{},errors:[]}; report.providers.push(record);
 const rpc=async(method,params=[])=>{record.rpcMethods.push(method); const resp=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:record.rpcMethods.length,method,params}),signal:AbortSignal.timeout(25000)}); if(!resp.ok)throw Error('HTTP '+resp.status); const result=await resp.json(); if(result.error)throw Error(JSON.stringify(result.error)); if(!('result'in result))throw Error('Missing RPC result'); return result.result;};
 const read=async(name,method,params,convert=x=>x)=>{try{const value=await rpc(method,params);record.reads[name]=convert(value);return value;}catch(e){record.errors.push({name,method,message:String(e)});return null;}};
 const chain=await read('chainId','eth_chainId',[],x=>Number(BigInt(x))); if(chain!=='0xb1'){record.errors.push({name:'chainId',message:'Wrong or unavailable chain; no further reads'});continue;}
 await read('fixedBlock','eth_getBlockByNumber',[fixed,false],b=>({number:BigInt(b.number).toString(),hash:b.hash,timestamp:BigInt(b.timestamp).toString(),gasLimit:BigInt(b.gasLimit).toString()}));
 await read('latestBlock','eth_getBlockByNumber',['latest',false],b=>({number:BigInt(b.number).toString(),hash:b.hash,timestamp:BigInt(b.timestamp).toString(),baseFeePerGas:b.baseFeePerGas?BigInt(b.baseFeePerGas).toString():null}));
 await read('deployerCodeFixed','eth_getCode',[from,fixed]);
 const latest=await read('latestNonce','eth_getTransactionCount',[from,'latest'],x=>BigInt(x).toString()); const pending=await read('pendingNonce','eth_getTransactionCount',[from,'pending'],x=>BigInt(x).toString());
 if(latest!==null&&pending!==null){record.reads.nonceConflict=latest!==pending;const predicted=getContractAddress({from,nonce:BigInt(latest)});record.reads.predictedCreateAddress=predicted; await read('predictedAddressCodeLatest','eth_getCode',[predicted,'latest']);}
 await read('gasPriceWei','eth_gasPrice',[],x=>BigInt(x).toString());
 await read('poolCodeFixed','eth_getCode',['0x4ff515761864e7838b0adb8b5b2b8b7a068905dc',fixed],x=>({bytes:(x.length-2)/2,keccak256:keccak256(x)}));
 await read('constructorCall','eth_call',[{from,data,value:'0x0',gas:'0x1c9c380'},fixed],runtime=>{assert((runtime.length-2)/2===12265); const mask=hex=>{let b=Buffer.from(hex.slice(2),'hex');for(const refs of Object.values(artifact.deployedBytecode.immutableReferences))for(const {start,length}of refs)b.fill(0,start,start+length);return '0x'+b.toString('hex');};assert.equal(mask(runtime),mask(artifact.deployedBytecode.object));return {status:'SUCCESS_RUNTIME_RETURNED',bytes:(runtime.length-2)/2,keccak256:keccak256(runtime),immutableMaskedStructureMatches:true,immutableValues:'NOT_ALL_INDEPENDENTLY_VERIFIED_BY_THIS_ETH_CALL',transactionHash:null};});
}
report.finishedAt=new Date().toISOString(); report.errors=report.providers.flatMap(p=>p.errors.map(e=>({endpoint:p.endpoint,...e})));report.status=report.errors.length?'PARTIAL_READS_WAITING_GAS':'READS_VERIFIED_WAITING_GAS_NOT_APPROVAL';
fs.writeFileSync(dir+'creation-readonly.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
